import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { env } from '../config/env.js';

const storageRoot = path.resolve(env.STORAGE_PATH);

function resolvePath(key: string): string {
  const resolved = path.resolve(storageRoot, key);
  // Defense in depth against a malformed/crafted key escaping the storage root —
  // in practice keys are always generated by generateKey() below, never user input.
  if (
    resolved !== storageRoot &&
    !resolved.startsWith(storageRoot + path.sep)
  ) {
    throw new Error('Invalid storage key');
  }
  return resolved;
}

export const localStorage = {
  // Storage keys are opaque and never exposed to clients directly — access always
  // goes through the authenticated /attachments/:attachmentId/download endpoint,
  // which resolves the key server-side from the verified attachment row.
  generateKey(taskId: number, originalFilename: string): string {
    const ext = path.extname(originalFilename);
    const random = randomBytes(16).toString('hex');
    return `tasks/${taskId}/${random}${ext}`;
  },

  async save(key: string, data: Buffer): Promise<void> {
    const filePath = resolvePath(key);
    await mkdir(path.dirname(filePath), { recursive: true });
    await writeFile(filePath, data);
  },

  async read(key: string): Promise<Buffer> {
    return readFile(resolvePath(key));
  },

  async delete(key: string): Promise<void> {
    await rm(resolvePath(key), { force: true });
  }
};
